-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') SELECT 'fato_pedidos' fato,count(*) linhas,count(DISTINCT order_id) pedidos,NULL::numeric price,NULL::numeric freight_value,NULL::numeric payment_value FROM p UNION ALL SELECT 'fato_itens_pedido' fato,count(*) linhas,count(DISTINCT order_id) pedidos,sum(price) price,sum(freight_value) freight_value,NULL::numeric payment_value FROM i UNION ALL SELECT 'fato_pagamentos' fato,count(*) linhas,count(DISTINCT order_id) pedidos,NULL::numeric price,NULL::numeric freight_value,sum(payment_value) payment_value FROM g;
